const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wilmington = ee.Geometry.Point([-77.8868, 34.2104]).buffer(50000); // 50km buffer around Wilmington
  const startDate = '2018-01-01';
  const endDate = '2018-12-31';

  // 2. Data Acquisition - CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(wilmington);

  const collectionSize = chirps.size().getInfo();
  console.log(`2018 CHIRPS Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum annual precipitation
  const annualPrecip = chirps.sum();

  // Check for valid pixels
  const pixelCount = annualPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wilmington,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid Pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation in mm, convert to inches
  const precipMm = annualPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wilmington,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  if (precipMm === null || precipMm === undefined || !isFinite(precipMm)) {
    console.log("<answer>C3</answer>");
    return;
  }

  const precipInches = precipMm / 25.4; // Convert mm to inches

  console.log(`Annual Precipitation: ${precipInches.toFixed(1)} inches`);
  console.log(`Target: 90 inches`);

  // 5. Validation & Final Answer
  if (precipInches >= 90) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
